SELECT DISTINCT p.post_id, p.user_id, p.title, p.content, p.category, p.image_url, p.salon_id, p.view_count, p.like_count, p.dislike_count, p.report_count, p.status, p.created_at, p.updated_at, COALESCE(u.user_name, '익명') AS author_name, s.salon_name AS salon_name FROM Posts p LEFT JOIN Users u ON p.user_id = u.user_id LEFT JOIN Salons s ON p.salon_id = s.salon_id
LEFT JOIN Comments c ON p.post_id = c.post_id
WHERE
(p.title LIKE #{keyword} OR p.content LIKE #{keyword})
p.content LIKE #{keyword}
c.content LIKE #{keyword}
u.user_name LIKE #{keyword}
s.salon_name LIKE #{keyword}
(p.title LIKE #{keyword} OR p.content LIKE #{keyword})
AND p.status = 'visible'
ORDER BY p.like_count DESC, p.created_at DESC
ORDER BY p.created_at DESC
